targets.expr:
(
  sum(sum_over_time(TPAPupi_tpap_gateway_metrics_downstream_http_status_code_value{
    environment="prod",
    app="tpap-gwts-ocil-switch-yes",
    http_status_code="200 OK"
  }[$__interval]))
  +
  sum(sum_over_time(TPAPupi_tpap_gateway_metrics_downstream_response_status_value{
    environment="prod",
    app="tpap-gwts-ocil-switch-yes",
    response_status="SUCCESS"
  }[$__interval]))
)
/
(
  sum(sum_over_time(TPAPupi_tpap_gateway_metrics_downstream_http_status_code_value{
    environment="prod",
    app="tpap-gwts-ocil-switch-yes"
  }[$__interval]))
  +
  sum(sum_over_time(TPAPupi_tpap_gateway_metrics_downstream_response_status_value{
    environment="prod",
    app="tpap-gwts-ocil-switch-yes"
  }[$__interval]))
)
* 100

avg(
  1000 * sum by(pod) (
    rate(
      container_cpu_usage_seconds_total{
        namespace="$namespace", 
        k8scluster="$cluster",
        container="",
        pod=~"$Application-[A-Za-z0-9]+-[A-Za-z0-9]+"
      }[1m]
    )
  ) 
  / sum by(pod) (
    kube_pod_container_resource_requests{
      namespace="$namespace", 
      pod=~"$Application-[A-Za-z0-9]+-[A-Za-z0-9]+", 
      resource="cpu"
    } * 1000
  )
) * 100

